function createSearchIndex(lunr, documents, serializedIndex) {
    // Lunr copies the tokenizer separator into its query lexer when it loads.
    // Split code names such as fmt.Println("x") in both documents and queries.
    lunr.tokenizer.separator = lunr.QueryLexer.termSeparator = /[\s\-."]+/;

    if (serializedIndex) return lunr.Index.load(serializedIndex);

    return lunr(function () {
        this.ref('id');
        this.field('title');
        this.field('body');
        // Queries need the same punctuation trimming as indexed terms.
        this.searchPipeline.before(lunr.stemmer, lunr.trimmer);
        documents.forEach(function (doc) {
            this.add(doc);
        }, this);
    });
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = createSearchIndex;
}

