var idx = createSearchIndex(lunr, documents, serializedIndex);
var resultsDiv = document.getElementById('lunrsearchresults');

function escapeHtml(text) {
    return text.replace(/[&<>"']/g, function (c) {
        return '&#' + c.charCodeAt(0) + ';';
    });
}

function lunr_search(term) {
    term = term.trim();
    if (!term) return;

    resultsDiv.style.display = '';
    document.body.classList.add('modal-open');
    resultsDiv.innerHTML = '<div id="resultsmodal" class="modal fade show d-block" tabindex="-1" role="dialog" aria-labelledby="lunrsearchtitle"><div class="modal-dialog shadow-lg" role="document"><div class="modal-content"><div class="modal-header"><h5 class="modal-title" id="lunrsearchtitle"></h5><button type="button" class="close lunrsearchclose" aria-label="Close">&times;</button></div><div class="modal-body"><ul class="mb-0"></ul></div><div class="modal-footer"><button type="button" class="btn btn-danger btn-sm lunrsearchclose">Close</button></div></div></div></div>';
    document.getElementById('lunrsearchtitle').textContent = "Search results for '" + term + "'";

    var results;
    try {
        // Keep Lunr's syntax, including +required and -excluded terms.
        results = idx.search(term);
    } catch (e) {
        // QueryParseError (for example "foo:" or "~") is a no-results search.
        results = [];
    }
    var list = resultsDiv.querySelector('ul');
    if (results.length > 0) {
        var html = '';
        for (var i = 0; i < results.length; i++) {
            var doc = documents[results[i].ref];
            var url = escapeHtml(doc.url);
            var title = escapeHtml(doc.title);
            var body = escapeHtml(doc.body.substring(0, 160) + '...');
            html += "<li class='lunrsearchresult'><a href='" + url + "'><span class='title'>" + title + "</span><br /><small><span class='body'>" + body + "</span><br /><span class='url'>" + url + "</span></small></a></li>";
        }
        list.innerHTML = html;
    } else {
        list.innerHTML = "<li class='lunrsearchresult'>Sorry, no results found. Close & try a different search!</li>";
    }
    // This dialog takes focus but does not trap Tab, so it makes no aria-modal promise.
    document.getElementById('resultsmodal').focus();
}

function closeResults() {
    resultsDiv.style.display = 'none';
    document.body.classList.remove('modal-open');
    document.getElementById('lunrsearch').focus();
}

resultsDiv.addEventListener('click', function (event) {
    if (event.target.closest('.lunrsearchclose') || event.target.id === 'resultsmodal') {
        closeResults();
    }
});
resultsDiv.addEventListener('keydown', function (event) {
    if (event.key === 'Escape') {
        // Results live inside the navbar: do not also close its mobile menu.
        event.stopPropagation();
        closeResults();
    }
});
